#!/usr/bin/env bash
# Agent Memory Challenge 适配服务 - 一键覆盖+重启 (自包含, 无需 scp)
# 只覆盖 app.py / requirements.txt, 绝不碰 .env (真密钥保留)
set -e
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cd "$SCRIPT_DIR"
echo "[1/5] 覆盖 app.py ..."
echo '' | base64 -d > app.py
echo "[2/5] 覆盖 requirements.txt ..."
echo '' | base64 -d > requirements.txt
echo "[3/5] 杀旧进程 ..."
pkill -f "app.py" || true
sleep 1
echo "[4/5] setsid 常驻重启 (miniconda3-aml python3.8) ..."
setsid ~/miniconda3-aml/bin/python app.py > aml.log 2>&1 &
sleep 3
echo "[5/5] 冒烟测试 ..."
TOKEN="$(grep -E '^(AML_API_KEY|LDBD_KEY)=' .env 2>/dev/null | head -1 | cut -d= -f2-)"
if [ -z "$TOKEN" ]; then
  ~/miniconda3-aml/bin/python smoke_test.py http://127.0.0.1:8080 ""
else
  ~/miniconda3-aml/bin/python smoke_test.py http://127.0.0.1:8080 "$TOKEN"
fi
echo "=== 部署脚本结束 ==="
